Lemma pf_L6_all : forall n, PF_L6_AT (Z.of_nat n).
Proof.
  induction n as [|n IH].
  - intros p. intros until g. intros CTX PURE BSZ SZ8 SZT SZV PL P2 N1 NP BI MEAS. exfalso. cbn in MEAS. lia.
  - rewrite Nat2Z.inj_succ. replace (Z.succ (Z.of_nat n)) with (Z.of_nat n + 1) by lia. apply pf_L6_step. exact IH.
Qed.

